export const sources=[
{id:'raissi2017',name:'Raissi, Perdikaris & Karniadakis, Physics Informed Deep Learning (2017), Parts I and II',url:'https://maziarraissi.github.io/PINNs/',text:'Open author exposition and code for differentiable solution networks, PDE residuals, initial/boundary observations, and forward/inverse modelling. Author manuscripts: https://arxiv.org/abs/1711.10561 and https://arxiv.org/abs/1711.10566 .'},
{id:'wang2023',name:'Wang, Sankaran, Wang & Perdikaris, An Expert’s Guide to Training PINNs (2023)',url:'https://arxiv.org/html/2308.08468v1',text:'Open manuscript covering nondimensionalization, architecture, loss balancing, temporal causality, curriculum, sampling and boundary constraints. Practical methods are problem-dependent and are not universal convergence guarantees.'},
{id:'failure2021',name:'Krishnapriyan et al., Characterizing Possible Failure Modes in PINNs (2021)',url:'https://arxiv.org/html/2109.01050v1',text:'Open manuscript demonstrating optimisation failures for convection, reaction and reaction-diffusion problems and investigating curriculum and sequential-in-time training. Expressive networks need not be easy to optimize.'},
{id:'torchdocs',name:'PyTorch official autograd tutorial',url:'https://docs.pytorch.org/tutorials/beginner/introyt/autogradyt_tutorial.html',text:'Official graph-based automatic differentiation documentation. The independent lab uses torch.autograd.grad(create_graph=True) for coordinate derivatives that remain differentiable with respect to network weights.'},
{id:'heatdocs',name:'DeepXDE official heat-equation example',url:'https://deepxde.readthedocs.io/en/latest/demos/pinn_forward/heat.html',text:'Official heat example with sinusoidal initial data and zero Dirichlet boundaries. This course independently chooses a dimensionless unit domain, alpha=0.1 and exp(-alpha*pi^2*t)*sin(pi*x), rather than reproducing published accuracy claims.'},
{id:'course-demo',name:'Independent locally executed PINN experiment',url:'/learn/pinns/classroom/demos/pinns_train.py',text:'Synthetic dimensionless heat problem: alpha=0.1, sine initial data, zero boundary values. Small smooth PyTorch networks trained on CPU with seed 7 in forward, inverse and omitted-initial-condition configurations. Held-out relative L2 and independent residual checks are logged. Inverse observations include Gaussian noise with standard deviation 0.005. These are teaching runs, not paper benchmarks.'}
];
